int longestConsecutive(const vector<int>& nums) {
    unordered_set<int> s(nums.begin(), nums.end());
    int best = 0;
    for (int x : s) {
        if (s.count(x - 1)) continue;      // not a head; someone else will count it
        int len = 1, cur = x;
        while (s.count(cur + 1)) { ++cur; ++len; }
        best = max(best, len);
    }
    return best;
}

