def longest_consecutive(nums: list[int]) -> int:
    s = set(nums)
    best = 0
    for x in s:
        if x - 1 in s:
            continue                 # not a head; someone else will count it
        cur, length = x, 1
        while cur + 1 in s:
            cur += 1
            length += 1
        best = max(best, length)
    return best

