def group_anagrams(words: list[str]) -> list[list[str]]:
    groups = {}
    for w in words:
        cnt = [0] * 26
        for c in w:
            cnt[ord(c) - ord('a')] += 1
        key = tuple(cnt)          # equality-canonical; readability is irrelevant
        groups.setdefault(key, []).append(w)
    return list(groups.values())

