int subarraySum(const vector<int>& nums, int k) {
    unordered_map<long long,int> count;
    count[0] = 1;                       // the empty prefix, so a whole-array match counts
    long long prefix = 0;
    int total = 0;
    for (int x : nums) {
        prefix += x;
        auto it = count.find(prefix - k);   // probe BEFORE inserting
        if (it != count.end()) total += it->second;
        ++count[prefix];
    }
    return total;
}

vector<vector<int>> kClosest(vector<vector<int>>& points, int k) {
    auto d2 = [](const vector<int>& p) {
        return (long long)p[0]*p[0] + (long long)p[1]*p[1];   // no sqrt needed
    };
    nth_element(points.begin(), points.begin() + k, points.end(),
        [&](const vector<int>& a, const vector<int>& b) { return d2(a) < d2(b); });
    return vector<vector<int>>(points.begin(), points.begin() + k);
}

