import heapq


def k_closest(points: list[list[int]], k: int) -> list[list[int]]:
    # size-k MAX-heap on squared distance: O(n log k) time, O(k) space
    heap = []                                  # (-dist2, x, y)
    for x, y in points:
        d2 = x * x + y * y                     # no sqrt needed
        if len(heap) < k:
            heapq.heappush(heap, (-d2, x, y))
        elif -heap[0][0] > d2:
            heapq.heapreplace(heap, (-d2, x, y))
    return [[x, y] for _, x, y in heap]

