            auto it = tweets.find(u);
            if (it != tweets.end() && !it->second.empty()) {
                int idx = (int)it->second.size() - 1;
                pq.push({it->second[idx].first, u, idx});
            }
        };
        seed(userId);
        for (int f : following[userId]) if (f != userId) seed(f);

        vector<int> out;
