import heapq


class Twitter:
    def __init__(self):
        self.clock = 0
        self.tweets = {}        # user -> list of (time, tweetId)
        self.following = {}     # user -> set of followees

    def post_tweet(self, user_id: int, tweet_id: int) -> None:
        self.tweets.setdefault(user_id, []).append((self.clock, tweet_id))
        self.clock += 1

    def get_news_feed(self, user_id: int) -> list[int]:
        # max-heap over (-time, user, index) seeded with each source's newest
        pq = []
        sources = {user_id} | self.following.get(user_id, set())
        for u in sources:
            lst = self.tweets.get(u)
            if lst:
                idx = len(lst) - 1
                heapq.heappush(pq, (-lst[idx][0], u, idx))
        out = []
        while pq and len(out) < 10:
            _, u, idx = heapq.heappop(pq)
            out.append(self.tweets[u][idx][1])
            if idx > 0:
                heapq.heappush(pq, (-self.tweets[u][idx-1][0], u, idx-1))
        return out

    def follow(self, a: int, b: int) -> None:
        self.following.setdefault(a, set()).add(b)

    def unfollow(self, a: int, b: int) -> None:
        self.following.get(a, set()).discard(b)   # tweets survive

