class RandomizedCollection {
    vector<int> vals;
    unordered_map<int, unordered_set<int>> idx;   // value -> positions holding it
public:
    bool insert(int val) {
        bool isNew = idx[val].empty();
        idx[val].insert((int)vals.size());
        vals.push_back(val);
        return isNew;
    }
    bool remove(int val) {
        auto it = idx.find(val);
        if (it == idx.end() || it->second.empty()) return false;
        int pos = *it->second.begin();
        it->second.erase(pos);

        int last = (int)vals.size() - 1;
        if (pos != last) {                    // identity check: skip the self-swap
            int moved = vals[last];
            vals[pos] = moved;
            idx[moved].erase(last);
            idx[moved].insert(pos);
        }
        vals.pop_back();
        return true;
    }
    int getRandom() { return vals[rand() % vals.size()]; }
};
